static long compressTimeBucket(long timeBucket,int dayStep){
    if (dayStep <= 0) {
        return timeBucket;
    }
    long year = timeBucket / 10000;
    long month = (timeBucket / 100) % 100;
    long day = timeBucket % 100;
    long newDay = ((day - 1) / dayStep) * dayStep + 1;
    return year * 10000 + month * 100 + newDay;
}

int function ( final CharSequence str, final int index, final int len ) {
    if ( str == null || len <= 0 ) {
        return 0;
    }
    int size = 0;
    int end = index + len;
    int strLen = str.length();
    if ( end > strLen ) {
        end = strLen;
    }
    for ( int i = index; i < end; i++ ) {
        char c = str.charAt( i );
        if ( c <= 0x7F ) {
            size += 1;
        } else if ( c <= 0x7FF ) {
            size += 2;
        } else {
            if ( Character.isHighSurrogate( c ) && i + 1 < end ) {
                char low = str.charAt( i + 1 );
