public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> segments = new ArrayList<>();
    if (u == null) {
        return segments;
    }
    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return segments;
    }
    // Remove leading '/' if present (absolute path)
    if (path.startsWith("/")) {
        path = path.substring(1);
    }
    // Split on '/' to get individual segments
    String[] parts = path.split("/");
    for (String part : parts) {
        if (part.isEmpty()) {
            continue;
        }
        String decoded = part;
        if (decode) {
            try {
                decoded = java.net.URLDecoder.decode(part, "UTF-8");
            } catch (java.io.UnsupportedEncodingException e) {
                throw new RuntimeException(e);
            }
        }
        // Create a PathSegmentImpl instance.  If the constructor requires
        // both original and decoded values, adjust accordingly.
        segments.add(new PathSegmentImpl(decoded));
    }
    return segments;
}

