private void pop(final String descriptor) {
    int i = 0;
    if (descriptor.charAt(0) == '(') {
        // method descriptor: pop argument types only
        i = 1;
        while (descriptor.charAt(i) != ')') {
            char c = descriptor.charAt(i);
            if (c == 'J' || c == 'D') {
                // long and double occupy two slots
                pos -= 2;
                i++;
            } else if (c == 'L') {
                // object type: skip until ';'
                i = descriptor.indexOf(';', i) + 1;
                pos--;
            } else if (c == '[') {
                // array type: skip all '[' and then the element type
                i++;
                while (descriptor.charAt(i) == '[') {
                    i++;
                }
                if (descriptor.charAt(i) == 'L') {
                    i = descriptor.indexOf(';', i) + 1;
                } else {
                    i++;
                }
                pos--;
            } else {
                // primitive type
                pos--;
                i++;
            }
        }
        // skip the ')' and ignore the return type
    } else {
        // single type descriptor
        char c = descriptor.charAt(i);
        if (c == 'J' || c == 'D') {
            pos -= 2;
        } else if (c == 'L') {
            pos--;
        } else if (c == '[') {
            i++;
            while (descriptor.charAt(i) == '[') {
                i++;
            }
            if (descriptor.charAt(i) == 'L') {
                i = descriptor.indexOf(';', i) + 1;
            } else {
                i++;
            }
            pos--;
        } else {
            pos--;
        }
    }
}

