static String[] toNoNullStringArray(Object[] array){
    if (array == null) return null;
    int count = 0;
    for (Object o : array) if (o != null) count++;
    if (count == array.length) {
        return (String[]) array;
    }
    String[] result = new String[count];
    int idx = 0;
    for (Object o : array) {
        if (o != null) {
            result[idx++] = (String) o;
        }
    }
    return result;
}

Edge edgeToNext(){
    Node prev = this._currentNode;
    Node next = this._nextNode;
    if(prev == null || next == null){
        return null;
    }
    Node realPrev = prev.isVirtual() ? prev.getRealNode() : prev;
    Node realNext = next.isVirtual() ? next.getRealNode() : next;
    for(Edge e : this._edges){
        if(e.getFrom() == realPrev && e.getTo() == realNext){
            return e;
        }
    }
    return null;
}

public static boolean substringMatch(CharSequence str,int index,CharSequence substring){
    if(str==null || substring==null) return false;
    int len = substring.length();
    if(index<0 || index+len>str.length()) return false;
    for(int i=0;i<len;i++){
        if(str.charAt(index+i)!=substring.charAt(i)) return false;
    }
    return true;
}

